import{_ as e,o as d,c as a,a3 as o}from"./chunks/framework.BLaSdaBb.js";const m=JSON.parse('{"title":"组织架构","description":"","frontmatter":{},"headers":[],"relativePath":"backend/organization.md","filePath":"backend/organization.md","lastUpdated":1786258579000}'),r={name:"backend/organization.md"};function c(n,t,s,i,l,h){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="组织架构" tabindex="-1">组织架构 <a class="header-anchor" href="#组织架构" aria-label="Permalink to &quot;组织架构&quot;">​</a></h1><p>组织架构回答的是「<strong>这个人在公司里是谁</strong>」：属于哪个部门、担任什么岗位、能看到哪个范围的数据。它是数据范围（<code>DepartmentOnly</code> / <code>DepartmentAndChildren</code>）的底座，也是消息定向的依据。</p><blockquote><p>用户主体与登录见 <a href="./authentication">身份与认证</a>；数据范围如何参与鉴权见 <a href="./permission">权限模型</a>；跨租户的成员关系见 <a href="./multi-tenancy">多租户与版本</a>。</p></blockquote><h2 id="三个主体" tabindex="-1">三个主体 <a class="header-anchor" href="#三个主体" aria-label="Permalink to &quot;三个主体&quot;">​</a></h2><table tabindex="0"><thead><tr><th>实体</th><th>表</th><th>定位</th></tr></thead><tbody><tr><td><code>SysDepartment</code></td><td><code>Sys_Department</code></td><td>组织架构树节点（<strong>严格单父树</strong>）</td></tr><tr><td><code>SysDepartmentHierarchy</code></td><td><code>Sys_Department_Hierarchy</code></td><td>部门层级<strong>闭包表</strong>（查询加速镜像）</td></tr><tr><td><code>SysPosition</code></td><td><code>Sys_Position</code></td><td><strong>扁平</strong>岗位字典（职务/职位），不成树</td></tr><tr><td><code>SysUserDepartment</code></td><td><code>Sys_User_Department</code></td><td>用户 ↔ 部门的多对多归属，承载岗位、工号、职级、入职日期</td></tr></tbody></table><p>前端页面：<code>/identity/org</code>（组织机构）与 <code>/identity/position</code>（岗位管理）。</p><h2 id="部门树与闭包表" tabindex="-1">部门树与闭包表 <a class="header-anchor" href="#部门树与闭包表" aria-label="Permalink to &quot;部门树与闭包表&quot;">​</a></h2><h3 id="为什么需要闭包表" tabindex="-1">为什么需要闭包表 <a class="header-anchor" href="#为什么需要闭包表" aria-label="Permalink to &quot;为什么需要闭包表&quot;">​</a></h3><p>数据范围 <code>DepartmentAndChildren</code>（本部门及下级）要回答「某部门的全部后代」。在邻接表（只有 <code>ParentId</code>）上这是递归查询，深树上很慢且难以下推到 SQL。</p><p><code>SysDepartmentHierarchy</code> 把<strong>所有「祖先-后代」对预计算出来</strong>（含 <code>Depth=0</code> 的自环），一次 <code>WHERE AncestorId = ?</code> 就能 O(1) 展开整棵子树。表里还冗余了 <code>Path</code> / <code>PathName</code> 便于直接渲染面包屑。</p><h3 id="闭包表是镜像-不是业务数据" tabindex="-1">闭包表是镜像，不是业务数据 <a class="header-anchor" href="#闭包表是镜像-不是业务数据" aria-label="Permalink to &quot;闭包表是镜像，不是业务数据&quot;">​</a></h3><p><strong>所有写入必须由 <code>SysDepartment</code> 的变更触发</strong>，<code>DepartmentDomainService</code> 在部门增/删/移时清空当前租户的闭包记录，再按全量部门整体重算（不是按子树增量维护）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新增部门        → 清空闭包记录，按全量部门重建</span></span>
<span class="line"><span>修改部门父级    → 清空闭包记录，按全量部门重建（仅 ParentId 变化时触发）</span></span>
<span class="line"><span>删除部门        → 清空闭包记录，按全量部门重建</span></span></code></pre></div><p>重建时逐个部门回溯祖先链，遇到自身重复（环路）或父级缺失会直接抛异常终止，不会写出半截闭包。仅改名称、联系方式、排序或启停状态不触发重建。</p><div class="warning custom-block"><p class="custom-block-title">绕过服务层直改 <code>Sys_Department</code> 会让闭包表失真</p><p>表现是数据范围算错——某些下级部门的数据看不到，或看到了本不该看到的。修复要走服务层重建闭包表，不要手工补行。</p></div><h2 id="岗位" tabindex="-1">岗位 <a class="header-anchor" href="#岗位" aria-label="Permalink to &quot;岗位&quot;">​</a></h2><p>岗位是<strong>扁平字典</strong>，不参与层级、不参与数据范围计算。它的作用是描述「这个人在这个部门里做什么」，被 <code>SysUserDepartment.PositionId</code> 引用。</p><p>岗位编码在租户内唯一（<code>Sys_Position</code> 的 <code>TenantId + PositionCode</code> 唯一索引）。</p><p>需要「岗位也有上下级」的场景，用角色层级（<code>SysRoleHierarchy</code>）表达，别把岗位改成树。</p><h2 id="用户归属" tabindex="-1">用户归属 <a class="header-anchor" href="#用户归属" aria-label="Permalink to &quot;用户归属&quot;">​</a></h2><p><code>SysUserDepartment</code> 是多对多关联，一个用户可以属于多个部门：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>UserId</code> / <code>DepartmentId</code></td><td>关联主体</td></tr><tr><td><code>IsMain</code></td><td><strong>主部门标识</strong>——组织架构展示取主部门（数据范围按全部有效归属计算），一个用户至多一个</td></tr><tr><td><code>PositionId</code></td><td>岗位（可空）</td></tr><tr><td>工号 / 职级 / 入职日期</td><td>人事属性</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">主部门唯一性靠服务层保证</p><p>表上没有「一个用户只能有一个主部门」的约束，是服务层在设置主部门时把其余归属的 <code>IsMain</code> 置 false；用户第一条部门归属会自动成为主部门，主归属被撤销或置无效时自动提升另一条有效归属。批量导入用户时要走同一条服务方法，别直接写表。</p></div><h2 id="与数据范围的关系" tabindex="-1">与数据范围的关系 <a class="header-anchor" href="#与数据范围的关系" aria-label="Permalink to &quot;与数据范围的关系&quot;">​</a></h2><p>数据范围是<strong>独立于权限码的另一个维度</strong>：权限码回答「能不能做这个操作」，数据范围回答「能对哪些行做」。</p><table tabindex="0"><thead><tr><th>数据范围（<code>DataPermissionScope</code>）</th><th>含义</th><th>依赖</th></tr></thead><tbody><tr><td><code>SelfOnly</code></td><td>仅本人</td><td>—</td></tr><tr><td><code>DepartmentOnly</code></td><td>本部门</td><td><code>SysUserDepartment</code> 的<strong>全部有效归属</strong></td></tr><tr><td><code>DepartmentAndChildren</code></td><td>本部门及下级</td><td>全部有效归属 + <strong>闭包表</strong>展开后代</td></tr><tr><td><code>All</code></td><td>全部数据</td><td>—</td></tr><tr><td><code>Custom</code></td><td>指定部门集合</td><td><code>Sys_Role_Data_Scope</code> / <code>Sys_User_Data_Scope</code></td></tr></tbody></table><p><code>Custom</code> 行上的 <code>IncludeChildren</code> 决定该部门是否连同后代一起展开。完整判定见 <a href="./permission">权限模型</a>。</p><div class="warning custom-block"><p class="custom-block-title">「有权限但查不到数据」多半是数据范围</p><p>返回 200 且列表为空、而不是 403——这是数据范围在起作用，不是 bug。排查顺序：用户的部门归属对不对 → 角色的数据范围设成了什么 → 闭包表是否完整。</p></div><h2 id="组织变更的连锁影响" tabindex="-1">组织变更的连锁影响 <a class="header-anchor" href="#组织变更的连锁影响" aria-label="Permalink to &quot;组织变更的连锁影响&quot;">​</a></h2><p>改组织架构不是改一张表，下面这些会跟着变：</p><table tabindex="0"><thead><tr><th>变更</th><th>连锁影响</th></tr></thead><tbody><tr><td>移动部门</td><td>闭包表整表重建 → 该子树下所有人的 <code>DepartmentAndChildren</code> 范围变化</td></tr><tr><td>增删用户部门归属</td><td>该用户的 <code>DepartmentOnly</code> / <code>DepartmentAndChildren</code> 范围变化</td></tr><tr><td>删除部门</td><td>存在子部门、用户归属、角色/用户数据范围引用或字段级安全引用时直接拒绝，必须先解除；删除后闭包表整表重建</td></tr><tr><td>任一变更</td><td>需失效 <code>SaasDepartmentTreeCacheItem</code>（<code>InvalidateOrganizationAsync</code>），涉及授权的还要失效授权快照</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">漏失效缓存 = 改完不生效</p><p>部门树走 Redis 缓存（<code>basicapp:saas:organization:dept-tree</code>）。写侧改完必须调 <code>ISaasCacheInvalidator.InvalidateOrganizationAsync()</code>，否则前端组织树、下拉选项都还是旧的。详见 <a href="./caching">缓存与异步</a>。</p></div><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./authentication">身份与认证</a>：用户主体、会话、登录</li><li><a href="./permission">权限模型</a>：数据范围如何参与鉴权</li><li><a href="./multi-tenancy">多租户与版本</a>：租户成员关系（与部门归属是两件事）</li><li><a href="./data-model#组织与租户">数据模型</a>：相关表结构</li></ul>`,34)])])}const b=e(r,[["render",c]]);export{m as __pageData,b as default};
